SELECT a.id, p.titel AS productie, a.datum, substr(a.start_at, 12, 5) AS start, o.naam AS venue, o.adres FROM activiteit a JOIN productie p ON p.id = a.productie_id AND p.deleted_at IS NULL LEFT JOIN speelreeks s ON s.id = a.speelreeks_id AND s.deleted_at IS NULL LEFT JOIN organisatie o ON o.id = COALESCE(a.locatie_id, s.locatie_id) AND o.deleted_at IS NULL WHERE a.deleted_at IS NULL AND a.soort = 'voorstelling' AND a.status = 'bevestigd'
